cypher:
UNWIND ['BV-6-1', 'CHV-10-1', 'CHV-10-2', 'CHV-10-3', 'CHV-3-1', 'CHV-6-1'] AS candidate_tag
OPTIONAL MATCH (v:PlantItem:Valve {tag: candidate_tag})
WITH candidate_tag, v,
     CASE WHEN v IS NOT NULL AND EXISTS {
       MATCH (u:PlantItem:Equipment {no_inflow: true})
       WHERE EXISTS { (u)-[:line_to*1..]->(v) }
         AND EXISTS { (v)-[:line_to*1..]->(:PlantItem {tag: 'P-16-2'}) }
     } THEN true ELSE false END AS on_flow_path
RETURN candidate_tag AS tag,
       on_flow_path,
       on_flow_path AS must_be_closed
ORDER BY tag
